//! The YARA module catalogue (`catalogs/yara/modules.toml`, generated by
//! `scripts/sync_yara_modules.py`) and the language data
//! (`catalogs/yara/language.toml`): profiles, keywords, known modules.
//! Each is parsed once per process.

use serde::Deserialize;
use std::collections::{BTreeMap, BTreeSet};
use std::sync::OnceLock;

const MODULES_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/yara/modules.toml"
));
const LANGUAGE_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/yara/language.toml"
));

/// A scalar type, or the shape of a module member.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Kind {
    Integer,
    Float,
    String,
    Boolean,
    Regexp,
    Struct,
    Array,
    Dict,
    Function,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Overload {
    /// libyara's one-letter argument types: `i`, `f`, `s`, `r`, `b`.
    pub args: String,
    pub ret: String,
    pub libyara: bool,
    pub yara_x: bool,
    /// YARA-X's return type where it differs from `ret` (a predicate libyara
    /// declares as an integer is a boolean in YARA-X).
    #[serde(default)]
    pub yara_x_ret: Option<String>,
    #[serde(default)]
    pub doc: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Member {
    pub module: String,
    /// `sections[].name`: `[]` is an array element, `{}` a dictionary value.
    pub path: String,
    pub kind: Kind,
    #[serde(default)]
    pub element: Option<Kind>,
    pub libyara: bool,
    pub yara_x: bool,
    /// YARA-X's type for a field where it differs from `kind`.
    #[serde(default)]
    pub yara_x_kind: Option<String>,
    #[serde(default)]
    pub doc: Option<String>,
    #[serde(default, rename = "overload")]
    pub overloads: Vec<Overload>,
}

#[derive(Deserialize)]
struct ModulesFile {
    member: Vec<Member>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ProfileData {
    pub dialect: String,
    pub ascii_only: bool,
    #[serde(default)]
    pub max_characters: Option<usize>,
    pub confirmed_modules: Vec<String>,
    pub recommended_meta: Vec<String>,
    #[serde(default)]
    pub context_values: Vec<String>,
}

#[derive(Deserialize)]
struct LanguageFile {
    known_modules: Vec<String>,
    keywords: Vec<String>,
    profile: BTreeMap<String, ProfileData>,
}

pub struct Catalog {
    /// `(module, path)` to member.
    members: BTreeMap<(String, String), Member>,
    /// Modules with at least one libyara 4.5 declaration.
    libyara_modules: BTreeSet<String>,
    pub known_modules: BTreeSet<String>,
    pub keywords: BTreeSet<String>,
    pub profiles: BTreeMap<String, ProfileData>,
}

impl Catalog {
    pub fn cached() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            let modules: ModulesFile =
                toml::from_str(MODULES_TOML).expect("catalogs/yara/modules.toml");
            let language: LanguageFile =
                toml::from_str(LANGUAGE_TOML).expect("catalogs/yara/language.toml");
            let libyara_modules = modules
                .member
                .iter()
                .filter(|m| m.libyara)
                .map(|m| m.module.clone())
                .collect();
            Catalog {
                members: modules
                    .member
                    .into_iter()
                    .map(|m| ((m.module.clone(), m.path.clone()), m))
                    .collect(),
                libyara_modules,
                known_modules: language.known_modules.into_iter().collect(),
                keywords: language.keywords.into_iter().collect(),
                profiles: language.profile,
            }
        })
    }

    pub fn member(&self, module: &str, path: &str) -> Option<&Member> {
        self.members.get(&(module.to_string(), path.to_string()))
    }

    /// The members directly under `path` (`""` is the module itself).
    pub fn children<'a>(
        &'a self,
        module: &'a str,
        path: &'a str,
    ) -> impl Iterator<Item = &'a Member> + 'a {
        self.members
            .range((module.to_string(), String::new())..)
            .take_while(move |((m, _), _)| m == module)
            .map(|(_, member)| member)
            .filter(move |member| parent_of(&member.path) == path)
    }

    /// Whether libyara 4.5 declares the module. `lnk` is in yara-1.0's list
    /// of known modules but not in libyara 4.5.4's sources: its members are
    /// checked against YARA-X's.
    pub fn has_libyara_declarations(&self, module: &str) -> bool {
        self.libyara_modules.contains(module)
    }
}

/// `sections[].name` -> `sections[]`; `imphash` -> `""`.
pub fn parent_of(path: &str) -> &str {
    path.rfind('.').map_or("", |i| &path[..i])
}

/// The last segment of a path, without `[]` or `{}`.
pub fn leaf_name(path: &str) -> &str {
    let leaf = path.rsplit('.').next().unwrap_or(path);
    leaf.trim_end_matches("[]").trim_end_matches("{}")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_loads_with_libyara_and_yara_x_rows() {
        let c = Catalog::cached();
        assert_eq!(c.known_modules.len(), 13);
        let name = c
            .member("pe", "sections[].name")
            .expect("pe.sections[].name");
        assert_eq!(name.kind, Kind::String);
        assert!(name.libyara && name.yara_x);
        let exports = c.member("pe", "exports").expect("pe.exports");
        assert!(exports.overloads.iter().any(|o| o.args == "s" && o.libyara));
        assert!(c.has_libyara_declarations("pe"));
        assert!(!c.has_libyara_declarations("lnk"));
        assert!(c.children("pe", "").any(|m| m.path == "number_of_sections"));
        assert!(c.keywords.contains("condition"));
        assert_eq!(c.profiles["bitdefender"].max_characters, Some(30000));
    }

    /// The checker lets a YARA-X boolean through an argument where a YARA-X
    /// overload takes one (`console.log(pe.is_dll())`). These are every
    /// such place: a sync that drops or adds one changes what is reported.
    #[test]
    fn yara_x_boolean_overloads_beside_number_ones() {
        let mut found = Vec::new();
        for m in Catalog::cached().members.values() {
            let ovs: Vec<&Overload> = m.overloads.iter().filter(|o| o.yara_x).collect();
            for o in &ovs {
                for (k, c) in o.args.chars().enumerate() {
                    let number = ovs.iter().any(|x| {
                        x.args.len() == o.args.len()
                            && matches!(x.args.chars().nth(k), Some('i' | 'f'))
                    });
                    if c == 'b' && number {
                        found.push(format!("{}.{}/{}:{k}", m.module, m.path, o.args.len()));
                    }
                }
            }
        }
        found.sort();
        found.dedup();
        assert_eq!(found, ["console.log/1:0", "console.log/2:1"]);
    }

    #[test]
    fn paths_split() {
        assert_eq!(parent_of("sections[].name"), "sections[]");
        assert_eq!(parent_of("imphash"), "");
        assert_eq!(leaf_name("sections[]"), "sections");
    }
}
